from shiny import App, ui, render

app_ui = ui.page_sidebar(
    ui.sidebar(ui.input_slider("x", "X", 0, 10, 1)),
    ui.output_text("out"),
)

def server(input, output, session):
    @output
    @render.text
    def out():
        return f"x is {input.x()}"

app = App(app_ui, server)

import reactive

@reactive.calc
def y():
    return input.x() * 2

@output
@render.text
def out():
    return f"y is {y()}"

@output
@render.text
def out2():
    return f"twice y is {y() * 2}"

@reactive.effect
def log():
    print("x is now", input.x())

from shiny import reactive

@output
@render.text
def out():
    # n is isolated — changing n does not re-run this
    return f"{input.x()} / {reactive.isolate(input.n())}"
